export interface ConnectorConfig {
  /** Brevo API key from environment variable BREVO_API_KEY */
  apiKey: string
  /** Static Brevo list ID to subscribe the contact to */
  listId: number
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      email?: string
      text?: string
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface HandleResult {
  contactId: number
}

function extractEmail(payload: TypeformWebhookPayload): string {
  const emailAnswer = payload.form_response.answers.find(
    (a) => a.field.type === 'email' && a.email
  )
  if (!emailAnswer?.email) {
    throw new Error('Required email field not found in Typeform response answers')
  }
  return emailAnswer.email
}

function extractName(payload: TypeformWebhookPayload): string | undefined {
  const nameAnswer = payload.form_response.answers.find(
    (a) => (a.field.type === 'short_text' || a.field.type === 'long_text') && a.text
  )
  return nameAnswer?.text
}

export async function handle(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!config.apiKey) {
    throw new Error('Missing required config: apiKey (BREVO_API_KEY)')
  }
  if (!config.listId) {
    throw new Error('Missing required config: listId')
  }

  const email = extractEmail(payload)
  const name = extractName(payload)

  const body = {
    email,
    attributes: name ? { FULLNAME: name } : {},
    listIds: [config.listId],
    updateEnabled: true,
  }

  const fetchImpl = config.fetch ?? fetch
  const response = await fetchImpl('https://api.brevo.com/v3/contacts', {
    method: 'POST',
    headers: {
      'api-key': config.apiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`Brevo API error: ${response.status} ${response.statusText} for POST https://api.brevo.com/v3/contacts`)
  }

  const data = (await response.json()) as { id: number }
  return { contactId: data.id }
}

